function generateUUID() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

return [{
  json: {
    run_id: generateUUID(),
    started_at: new Date().toISOString()
  }
}];

const text = $input.first().json.data;
const lines = text.trim().split('\n');
const headers = lines[0].split(',');

return lines.slice(1).map(line => {
  const values = line.split(',');
  const row = {};
  headers.forEach((header, i) => {
    row[header.trim()] = values[i]?.trim();
  });
  return { json: { ...row, source: "csv" } };
});

return $input.all().map(item => {
  const r = item.json.fields;
  return {
    json: {
      campaign_name: r.Name || r.campaign_name,
      date: r.date || r.Date,
      impressions: Number(r.Impressions || r.impressions || 0),
      clicks: Number(r.clicks || r.Clicks || 0),
      conversions: Number(r.conversions || r.Conversions || 0),
      spend: Number(r.spend || r.Spend || 0),
      source: "airtable",
      run_id: $('Create run_id').first().json.run_id
    }
  };
});

return $input.all().map(item => {
  const r = item.json;
  return {
    json: {
      campaign_name: r.campaign_name || r.Name || r.name,
      date: r.date || r.Date,
      impressions: Number(r.impressions || 0),
      clicks: Number(r.clicks || 0),
      conversions: Number(r.conversions || 0),
      spend: Number(r.spend || 0),
      source: "csv",
      run_id: $('Create run_id').first().json.run_id
    }
  };
});

const campaigns = $input.all().map(i => i.json);

// Calculate per-campaign metrics
const withMetrics = campaigns.map(c => {
  const ctr = c.impressions > 0 ? c.clicks / c.impressions : 0;
  const cpc = c.clicks > 0 ? c.spend / c.clicks : 0;
  const conversion_rate = c.clicks > 0 ? c.conversions / c.clicks : 0;

  return { ...c, ctr, cpc, conversion_rate };
});

// Calculate averages across all campaigns
const avg_ctr = withMetrics.reduce((s, c) => s + c.ctr, 0) / withMetrics.length;
const avg_conversion_rate = withMetrics.reduce((s, c) => s + c.conversion_rate, 0) / withMetrics.length;
const total_spend = withMetrics.reduce((s, c) => s + c.spend, 0);

// Find top performer by conversion rate
const top = withMetrics.reduce((a, b) => a.conversion_rate > b.conversion_rate ? a : b);

// Flag anomalies — campaigns >50% above or below average CTR
const withAnomalies = withMetrics.map(c => {
  let is_anomaly = false;
  let anomaly_reason = null;

  if (c.ctr > avg_ctr * 1.5) {
    is_anomaly = true;
    anomaly_reason = `CTR ${(c.ctr * 100).toFixed(2)}% is >50% above average`;
  } else if (c.ctr < avg_ctr * 0.5) {
    is_anomaly = true;
    anomaly_reason = `CTR ${(c.ctr * 100).toFixed(2)}% is >50% below average`;
  }

  return { ...c, is_anomaly, anomaly_reason };
});

// Pass each campaign forward with summary data attached
return withAnomalies.map(c => ({
  json: {
    ...c,
    avg_ctr,
    avg_conversion_rate,
    total_spend,
    top_performer: top.campaign_name
  }
}));

const campaigns = $input.all().map(i => i.json);

// Build campaign table for the prompt
const campaignTable = campaigns.map(c => 
  `- ${c.campaign_name} | CTR: ${(c.ctr * 100).toFixed(2)}% | CVR: ${(c.conversion_rate * 100).toFixed(2)}% | Spend: $${c.spend} | Source: ${c.source}${c.is_anomaly ? ` | ⚠️ ANOMALY: ${c.anomaly_reason}` : ''}`
).join('\n');

// Pick anomalies
const anomalies = campaigns.filter(c => c.is_anomaly).map(c => c.campaign_name).join(', ');

const prompt = `You are a senior marketing analyst. Write a concise 3-paragraph executive summary for a marketing director.

Campaign Performance Data:
${campaignTable}

Key Stats:
- Total spend: $${campaigns[0].total_spend}
- Average CTR: ${(campaigns[0].avg_ctr * 100).toFixed(2)}%
- Average CVR: ${(campaigns[0].avg_conversion_rate * 100).toFixed(2)}%
- Top performer: ${campaigns[0].top_performer}
- Anomalies detected: ${anomalies}

Requirements:
- Paragraph 1: Overall performance overview
- Paragraph 2: Highlight top performer and why it stands out
- Paragraph 3: Call out anomalies with actionable recommendations

Professional but accessible tone.`;

return [{ 
  json: { 
    prompt,
    top_performer: campaigns[0].top_performer,
    avg_ctr: campaigns[0].avg_ctr,
    avg_conversion_rate: campaigns[0].avg_conversion_rate,
    total_spend: campaigns[0].total_spend,
run_id: campaigns[0].run_id  } 
}];

const items = $input.all();

// Check if filters were passed from either trigger
const trigger = $('Click trigger').first().json;
const dateFrom = trigger?.date_from || null;
const dateTo = trigger?.date_to || null;
const campaignFilter = trigger?.campaign_filter || null;

if (!items || items.length === 0) {
  throw new Error('Dataset is empty — no campaigns to process.');
}

let filtered = items;

if (dateFrom || dateTo) {
  filtered = filtered.filter(item => {
    const date = new Date(item.json.date);
    if (dateFrom && date < new Date(dateFrom)) return false;
    if (dateTo && date > new Date(dateTo)) return false;
    return true;
  });
}

if (campaignFilter) {
  filtered = filtered.filter(item =>
    item.json.campaign_name?.toLowerCase().includes(campaignFilter.toLowerCase())
  );
}

if (filtered.length === 0) {
  throw new Error(`No campaigns match the given filters.`);
}

return filtered;
